{"query":"query DroppedCommits($owner: String!, $repo: String!, $number: Int!, $o0: GitObjectID!, $o1: GitObjectID!, $o2: GitObjectID!, $o3: GitObjectID!, $o4: GitObjectID!, $o5: GitObjectID!, $o6: GitObjectID!, $o7: GitObjectID!, $o8: GitObjectID!, $o9: GitObjectID!, $o10: GitObjectID!, $o11: GitObjectID!, $o12: GitObjectID!, $o13: GitObjectID!, $o14: GitObjectID!) {
  repository(owner: $owner, name: $repo) {
    c0: object(oid: $o0) { __typename ... on Commit { ...CommitFields } }
    c1: object(oid: $o1) { __typename ... on Commit { ...CommitFields } }
    c2: object(oid: $o2) { __typename ... on Commit { ...CommitFields } }
    c3: object(oid: $o3) { __typename ... on Commit { ...CommitFields } }
    c4: object(oid: $o4) { __typename ... on Commit { ...CommitFields } }
    c5: object(oid: $o5) { __typename ... on Commit { ...CommitFields } }
    c6: object(oid: $o6) { __typename ... on Commit { ...CommitFields } }
    c7: object(oid: $o7) { __typename ... on Commit { ...CommitFields } }
    c8: object(oid: $o8) { __typename ... on Commit { ...CommitFields } }
    c9: object(oid: $o9) { __typename ... on Commit { ...CommitFields } }
    c10: object(oid: $o10) { __typename ... on Commit { ...CommitFields } }
    c11: object(oid: $o11) { __typename ... on Commit { ...CommitFields } }
    c12: object(oid: $o12) { __typename ... on Commit { ...CommitFields } }
    c13: object(oid: $o13) { __typename ... on Commit { ...CommitFields } }
    c14: object(oid: $o14) { __typename ... on Commit { ...CommitFields } }
  }
}

fragment ActorFields on Actor { __typename login }

fragment PageInfoFields on PageInfo { hasNextPage endCursor }

fragment CheckRunFields on CheckRun {
  id
  name
  status
  conclusion
  startedAt
  completedAt
  detailsUrl
  url
  summary
  title
  isRequired(pullRequestNumber: $number)
}

fragment CheckRunsPage on CheckRunConnection {
  pageInfo { ...PageInfoFields }
  nodes { ...CheckRunFields }
}

fragment CheckSuiteFields on CheckSuite {
  id
  status
  conclusion
  createdAt
  updatedAt
  url
  app { slug name }
  push {
    id
    previousSha
    nextSha
    pusher { ...ActorFields }
  }
  workflowRun {
    id
    url
    workflow { name }
  }
  checkRuns(first: 50) { ...CheckRunsPage }
}

fragment CheckSuitesPage on CheckSuiteConnection {
  pageInfo { ...PageInfoFields }
  nodes { ...CheckSuiteFields }
}

fragment CommitFields on Commit {
  id
  oid
  abbreviatedOid
  messageHeadline
  committedDate
  authoredDate
  author {
    name
    user { ...ActorFields }
  }
  checkSuites(first: 10) { ...CheckSuitesPage }
}","variables":{"owner":"rust-lang","repo":"rust","number":137944,"o0":"b31fd852d73da6ea65b769871b8d002dccc098f1","o1":"b33e2c530407a34feb7606f0de4c40e18199b082","o2":"b78eea28d5fc084937f62dfad5b9a1c9e33cc857","o3":"b9912eefa4c60bbbbf766c74727eb85601d2180e","o4":"bd57ee3779a5e7e5b319ac875445f5e4152333ae","o5":"c290ee63f464aaf854112d6a9fd04fed44fb8392","o6":"c8d6c7140340a8d9371a9b4fdeebf306a7aee5ad","o7":"cee3fddcd30cab4077364404fff81da2b4431f71","o8":"e1ad8d3cda0a35b3299176fdbf3154d1e2465c71","o9":"e7511bd9b95ccd2a5be2141e7fe88993d6eb25b7","o10":"e93a8750408a1f92e1c9f04ea09bd38f801d051d","o11":"eb6710afdfbfa1ab345c3fe5d9545420fac5a6b1","o12":"f0bf7dbb76af07ff11e963f884c8372b6d4ed25a","o13":"fb4c0d9da02781b1137f3e810d94b23f41ab0476","o14":"fe6cd4115ac39feabb23c9d2b31ae67aa43d22ca"}}
